(function () {
  var AV = {"hero":"data:image/webp;base64,","paladin":"data:image/webp;base64,","darkknight":"data:image/webp;base64,","archmage-fp":"data:image/webp;base64,","archmage-il":"data:image/webp;base64,","bishop":"data:image/webp;base64,","bowmaster":"data:image/webp;base64,","marksman":"data:image/webp;base64,","pathfinder":"data:image/webp;base64,","nightlord":"data:image/webp;base64,","shadower":"data:image/webp;base64,","dualblade":"data:image/webp;base64,","viper":"data:image/webp;base64,","captain":"data:image/webp;base64,","cannoneer":"data:image/webp;base64,","mihile":"data:image/webp;base64,","soulmaster":"data:image/webp;base64,","flamewizard":"data:image/webp;base64,","windbreaker":"data:image/webp;base64,","nightwalker":"data:image/webp;base64,","striker":"data:image/webp;base64,","aran":"data:image/webp;base64,","evan":"data:image/webp;base64,","luminous":"data:image/webp;base64,","mercedes":"data:image/webp;base64,","phantom":"data:image/webp;base64,","eunwol":"data:image/webp;base64,","blaster":"data:image/webp;base64,","battlemage":"data:image/webp;base64,","wildhunter":"data:image/webp;base64,","xenon":"data:image/webp;base64,","mechanic":"data:image/webp;base64,","demonslayer":"data:image/webp;base64,","demonavenger":"data:image/webp;base64,","kaiser":"data:image/webp;base64,","kain":"data:image/webp;base64,","cadena":"data:image/webp;base64,","angelicbuster":"data:image/webp;base64,","zero":"data:image/webp;base64,","kinesis":"data:image/webp;base64,","adele":"data:image/webp;base64,","illium":"data:image/webp;base64,","khali":"data:image/webp;base64,","ark":"data:image/webp;base64,","ren":"data:image/webp;base64,","lara":"data:image/webp;base64,","hoyoung":"data:image/webp;base64,","lethe":"data:image/webp;base64,"};
  document.querySelectorAll('img[data-av]').forEach(function (el) { el.src = AV[el.dataset.av]; });
  var side = document.getElementById('side'), btn = document.getElementById('side-toggle'), scrim = document.getElementById('side-scrim');
  if (!side || !btn) return;
  function set(open) { side.classList.toggle('open', open); scrim.classList.toggle('on', open); btn.setAttribute('aria-expanded', open ? 'true' : 'false'); }
  btn.addEventListener('click', function () { set(!side.classList.contains('open')); });
  scrim.addEventListener('click', function () { set(false); });
  document.addEventListener('keydown', function (e) { if (e.key === 'Escape') set(false); });
  var cur = side.querySelector('[aria-current=page]');
  if (cur && cur.scrollIntoView) { var r = cur.getBoundingClientRect(), h = window.innerHeight; if (r.top < 0 || r.bottom > h) cur.scrollIntoView({ block: 'center' }); }
})();
